const defaultProvocationCategory = "general"

// The default category keeps provocations.json PERMANENTLY — that is the whole
// reason RFC_013 chose one file per category: every existing reader, engine
// included, goes on reading the file it already reads.
func feedFilename(category string) string {
    if category == defaultProvocationCategory { return "provocations.json" }
    return "provocations-" + category + ".json"
}

fc.Filename = feedFilename(fc.Category)
if v, ok := config["filename"].(string); ok && v != "" && v != fc.Filename {
    return fc, fmt.Errorf("filename %q contradicts category %q, which publishes %q ...", v, fc.Category, fc.Filename)
}

var errFeedNotPublished = fmt.Errorf("no feed is published at that path yet")

func shouldBootstrap(ferr error, builtArchiveCount int) bool {
    return errors.Is(ferr, errFeedNotPublished) && builtArchiveCount == 0
}

// in fetchServedFeed:
if resp.StatusCode == http.StatusNotFound { return nil, errFeedNotPublished }

// in the action:
switch {
case shouldBootstrap(ferr, next.ArchiveCount):  bootstrap = true; log...
case errors.Is(ferr, errFeedNotPublished):      /* non-empty archive: refuse unless overridden */
default:                                        /* unchanged: refuse unless overridden */
}

CREATE UNIQUE INDEX idx_provocations_one_per_category_day
    ON provocations (domain, category, publish_on)
    WHERE publish_on IS NOT NULL AND status = 'approved';
DROP INDEX IF EXISTS idx_provocations_one_per_day;

DO $verify$ ... -- induce: two categories one date => allowed; same category twice => unique_violation expected
  IF NOT refused THEN RAISE EXCEPTION '320: ... the one-per-category-per-day rule is gone'; END IF;

